```
import java.math.BigDecimal;
public class DecimalToBinary {
 public static void main(String[] args) {
 BigDecimal decimal = new BigDecimal("10.12345");
 BigDecimal two = new BigDecimal("2");
 int scale = 5;
 StringBuilder binary = new StringBuilder();
 BigDecimal integerPart = decimal.setScale(0, BigDecimal.ROUND_DOWN);
 BigDecimal fractionPart = decimal.subtract(integerPart);
 while (integerPart.compareTo(BigDecimal.ZERO) > 0) {
 binary.insert(0, integerPart.remainder(two));
 integerPart = integerPart.divide(two, 0, BigDecimal.ROUND_DOWN);
 }
 binary.append(".");
 while (fractionPart.compareTo(BigDecimal.ZERO) > 0 && scale > 0) {
 fractionPart = fractionPart.multiply(two);
 binary.append(fractionPart.compareTo(BigDecimal.ONE) >= 0 ? 1 : 0);
 fractionPart = fractionPart.subtract(fractionPart.setScale(0, BigDecimal.ROUND_DOWN));
 scale--;
 }
 System.out.println(binary);
 // Logic test
 BigDecimal binaryDecimal = new BigDecimal(binary.toString());
 BigDecimal originalDecimal = new BigDecimal("10.12345");
 System.out.println(binaryDecimal.compareTo(originalDecimal) == 0 ? "Conversion is accurate" : "Conversion is inaccurate");
 }
}
```
