are_anagrams <- function(str1, str2) {
 # Convert strings to lowercase and remove spaces
 str1 <- tolower(gsub(" ", "", str1))
 str2 <- tolower(gsub(" ", "", str2))

 # Check if the length of the strings are equal
 if (nchar(str1) != nchar(str2)) {
 return(FALSE)
 }

 # Sort the characters in both strings
 str1_sorted <- paste(sort(strsplit(str1, "")[[1]]), collapse="")
 str2_sorted <- paste(sort(strsplit(str2, "")[[1]]), collapse="")

 # Check if the sorted strings are equal
 if (str1_sorted == str2_sorted) {
 return(TRUE)
 } else {
 return(FALSE)
 }
}
# Example usage
