 const codeEnd = data.codeEnd;
 const codeSnippet = data.sentence.substring(data.sentence.indexOf(codeStart) + codeStart.length, data.sentence.indexOf(codeEnd));
 sentence.innerHTML = `${data.sentence.substring(0, data.sentence.indexOf(codeStart))}`${codeSnippet}`${data.sentence.substring(data.sentence.indexOf(codeEnd) + codeEnd.length)}`;
 document.body.appendChild(sentence);
 });
